SourceCode.Declaration:
/// <summary>
/// ATL specification of a released product (InventTable) as MD31 leaves it.
/// AtlSpecProductItem (AtlApplicationSuite) has no setter for TaraWeight,
/// OrigCountryRegionId or the SJP extension fields, so this spec covers the fields
/// MD31 writes in applyItemAttributes. Use with data.invent().items().query().withItemId(..).
/// </summary>
public final class TEST_AtlSpecMD31ReleasedItem extends AtlSpecification
{
}

Method.Source:
public static TEST_AtlSpecMD31ReleasedItem construct()
{
    return new TEST_AtlSpecMD31ReleasedItem();
}

public TEST_AtlSpecMD31ReleasedItem withItemId(ItemId _itemId)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, ItemId), _itemId);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withNameAlias(str _nameAlias)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, NameAlias), _nameAlias);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withNetWeight(real _netWeight)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, NetWeight), _netWeight);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withTaraWeight(real _taraWeight)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, TaraWeight), _taraWeight);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withGrossSize(real _depth, real _width, real _height)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, grossDepth),  _depth);
    this.parmExpectedFieldValue(fieldNum(InventTable, grossWidth),  _width);
    this.parmExpectedFieldValue(fieldNum(InventTable, grossHeight), _height);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withUnitVolume(real _unitVolume)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, UnitVolume), _unitVolume);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withBOMUnitId(str _unitId)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, BOMUnitId), _unitId);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withOrigCountryRegionId(str _countryRegionId)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, OrigCountryRegionId), _countryRegionId);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withParentJanFlag(NoYes _flag)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, SJPMDParentJANFlag), _flag);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withDepartmentCode(str _code)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, SJPMDDepartmentCode), _code);

    return this;
}

public TEST_AtlSpecMD31ReleasedItem withProductCategory(str _category)
{
    this.parmExpectedFieldValue(fieldNum(InventTable, SJPMDProductCategory), _category);

    return this;
}
